def gerar_pdf_relatorio(total_equipe, faixas_ok, totais, cobradores_list, n_excl, mes_ref):
    from reportlab.lib.pagesizes import A4
    from reportlab.lib import colors
    from reportlab.lib.styles import ParagraphStyle
    from reportlab.lib.units import cm
    from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, Table, TableStyle, HRFlowable
    buf = BytesIO()
    doc = SimpleDocTemplate(buf, pagesize=A4, leftMargin=2*cm, rightMargin=2*cm, topMargin=2*cm, bottomMargin=2*cm)
    navy=colors.HexColor("#041747"); yellow=colors.HexColor("#FAC318")
    green=colors.HexColor("#0F8C3B"); red=colors.HexColor("#991B1B")
    light=colors.HexColor("#F4F5F7"); mid=colors.HexColor("#E8EAF0"); gray=colors.HexColor("#6b7280")
    S = lambda name,**kw: ParagraphStyle(name,**kw)
    title_s  = S("t", fontName="Helvetica-Bold", fontSize=20, textColor=navy, spaceAfter=2)
    sub_s    = S("s", fontName="Helvetica",      fontSize=10, textColor=gray, spaceAfter=6)
    sec_s    = S("se",fontName="Helvetica-Bold", fontSize=11, textColor=navy, spaceBefore=14, spaceAfter=6)
    small_s  = S("sm",fontName="Helvetica",      fontSize=7,  textColor=gray)
    story = []
    # Header: logo texto à esquerda, info à direita
    left_cell = [
        Paragraph("GRUPO LLE", S("tl", fontName="Helvetica-Bold", fontSize=22, textColor=navy, spaceAfter=2)),
        Paragraph("Sistema de Premiacao — Equipe Financeiro", S("sl", fontName="Helvetica", fontSize=9, textColor=gray)),
    ]
    right_cell = [
        Paragraph("Relatorio Gerencial de Cobranca", S("tr", fontName="Helvetica", fontSize=9, textColor=gray, alignment=2, spaceAfter=2)),
        Paragraph(mes_ref, S("sr", fontName="Helvetica-Bold", fontSize=11, textColor=navy, alignment=2)),
    ]
    title_block = Table([[left_cell, right_cell]], colWidths=[11*cm, 6.7*cm])
    title_block.setStyle(TableStyle([
        ("VALIGN", (0,0), (-1,-1), "BOTTOM"),
        ("BOTTOMPADDING", (0,0), (-1,-1), 6),
        ("TOPPADDING", (0,0), (-1,-1), 0),
    ]))
    story.append(title_block)
    story.append(HRFlowable(width="100%", thickness=3, color=yellow, spaceBefore=8, spaceAfter=14))
    # KPIs
    premio_cob = sum(m["premio"]/2 for m in METAS if faixas_ok[m["col"]])
    n_ativos = len([n for n in cobradores_list if n not in COBRADORES_INATIVOS])
    kpi_t = Table([
        ["Cobradores ativos","Excluidos","Premio por cobrador","Premio por lider"],
        [str(n_ativos), str(n_excl), fmt_br(premio_cob), fmt_br(premio_cob)],
    ], colWidths=[4.25*cm, 4.25*cm, 4.25*cm, 4.25*cm])
    kpi_t.setStyle(TableStyle([
        ("BACKGROUND",(0,0),(-1,0),navy),("TEXTCOLOR",(0,0),(-1,0),colors.white),
        ("FONTNAME",(0,0),(-1,0),"Helvetica-Bold"),("FONTSIZE",(0,0),(-1,0),8),
        ("BACKGROUND",(0,1),(-1,1),light),("FONTNAME",(0,1),(-1,1),"Helvetica-Bold"),
        ("FONTSIZE",(0,1),(-1,1),14),("TEXTCOLOR",(0,1),(-1,1),navy),
        ("TEXTCOLOR",(2,1),(3,1),green),("ALIGN",(0,0),(-1,-1),"CENTER"),
        ("VALIGN",(0,0),(-1,-1),"MIDDLE"),("BOX",(0,0),(-1,-1),.5,mid),
        ("INNERGRID",(0,0),(-1,-1),.5,mid),("TOPPADDING",(0,0),(-1,-1),8),("BOTTOMPADDING",(0,0),(-1,-1),8),
    ]))
    story.append(kpi_t)
    story.append(Spacer(1,12))
    # Metas tabela
    story.append(Paragraph("Resultado por Faixa de Aging", sec_s))
    rows = [["Faixa","Meta","Recuperado equipe","Progresso","Status","Prêmio/cobrador"]]
    for m in METAS:
        val=total_equipe[m["col"]]; atingiu=faixas_ok[m["col"]]
        pct=round(val/m["meta"]*100,1) if m["meta"]>0 else 0
        rows.append([m["faixa"],fmt_br(m["meta"]),fmt_br(val),f"{pct}%","✓ Batida" if atingiu else "✗ Não batida",fmt_br(m["premio"]/2) if atingiu else "—"])
    total_aging = sum(total_equipe[m["col"]] for m in METAS[:-1])
    rows.append(["TOTAL AGING","—",fmt_br(total_aging),"—","—",fmt_br(premio_cob)])
    t = Table(rows, colWidths=[4.5*cm,2.4*cm,3*cm,1.8*cm,2.2*cm,2.8*cm])
    ts = TableStyle([
        ("BACKGROUND",(0,0),(-1,0),navy),("TEXTCOLOR",(0,0),(-1,0),colors.white),
        ("FONTNAME",(0,0),(-1,0),"Helvetica-Bold"),("FONTSIZE",(0,0),(-1,-1),8),
        ("FONTNAME",(0,1),(-1,-1),"Helvetica"),("ALIGN",(1,0),(-1,-1),"RIGHT"),("ALIGN",(0,0),(0,-1),"LEFT"),
        ("ROWBACKGROUNDS",(0,1),(-1,-2),[colors.white,light]),
        ("BACKGROUND",(0,-1),(-1,-1),mid),("FONTNAME",(0,-1),(-1,-1),"Helvetica-Bold"),
        ("BOX",(0,0),(-1,-1),.5,mid),("INNERGRID",(0,0),(-1,-1),.3,mid),
        ("TOPPADDING",(0,0),(-1,-1),5),("BOTTOMPADDING",(0,0),(-1,-1),5),
    ])
    for i,m in enumerate(METAS,1):
        if faixas_ok[m["col"]]: ts.add("TEXTCOLOR",(4,i),(5,i),green); ts.add("FONTNAME",(4,i),(5,i),"Helvetica-Bold")
        else: ts.add("TEXTCOLOR",(4,i),(4,i),red)
    t.setStyle(ts); story.append(t); story.append(Spacer(1,12))
    # Por cobrador
    story.append(Paragraph("Resultado Individual", sec_s))
    faixas_short = [m["faixa"][:10] for m in METAS]
    rows2 = [["Cobrador","Status"]+faixas_short+["Prêmio"]]
    for nome in cobradores_list:
        inativo=nome in COBRADORES_INATIVOS
        premio=0.0 if inativo else sum(m["premio"]/2 for m in METAS if faixas_ok[m["col"]])
        rows2.append([nome.replace("."," ").title(),"Inativo" if inativo else "Ativo"]+
                     [fmt_br(totais[nome][m["col"]]) for m in METAS]+[fmt_br(premio)])
    n_c=len(rows2[0]); cw=[3.2*cm,1.4*cm]+[1.65*cm]*(n_c-3)+[2.0*cm]
    t2=Table(rows2,colWidths=cw)
    ts2=TableStyle([
        ("BACKGROUND",(0,0),(-1,0),navy),("TEXTCOLOR",(0,0),(-1,0),colors.white),
        ("FONTNAME",(0,0),(-1,0),"Helvetica-Bold"),("FONTSIZE",(0,0),(-1,-1),7),
        ("FONTNAME",(0,1),(-1,-1),"Helvetica"),("ALIGN",(2,0),(-1,-1),"RIGHT"),("ALIGN",(0,0),(1,-1),"LEFT"),
        ("ROWBACKGROUNDS",(0,1),(-1,-1),[colors.white,light]),
        ("BOX",(0,0),(-1,-1),.5,mid),("INNERGRID",(0,0),(-1,-1),.3,mid),
        ("TOPPADDING",(0,0),(-1,-1),4),("BOTTOMPADDING",(0,0),(-1,-1),4),
    ])
    for i,nome in enumerate(cobradores_list,1):
        if nome in COBRADORES_INATIVOS: ts2.add("TEXTCOLOR",(0,i),(-1,i),colors.HexColor("#9ca3af"))
        else: ts2.add("TEXTCOLOR",(-1,i),(-1,i),green); ts2.add("FONTNAME",(-1,i),(-1,i),"Helvetica-Bold")
    t2.setStyle(ts2); story.append(t2); story.append(Spacer(1,12))
    story.append(HRFlowable(width="100%",thickness=1,color=mid,spaceAfter=6))
    story.append(Paragraph(f"Gerado em {datetime.now().strftime('%d/%m/%Y %H:%M')} · Grupo LLE · Uso interno", small_s))
    doc.build(story); buf.seek(0); return buf


