def kpi_card(label, value, color="#041747", top_color=None):
    tc = top_color or color
    return ('<div class="lle-kpi" style="border-top:3px solid ' + tc + ';">' +
            '<div class="lle-kpi-label">' + label + '</div>' +
            '<div class="lle-kpi-value" style="color:' + color + '">' + str(value) + '</div></div>')

def info_strip(content):
    return '<div class="lle-strip">' + content + '</div>'

# ── Constantes ───────────────────────────────────────────────────────────
METAS = [
    {"faixa":"Curto prazo (10–30d)",     "col":"De 0 a 30",     "meta":700000,"premio":260},
    {"faixa":"Médio prazo (31–60d)",      "col":"De 31 a 60",    "meta":120000,"premio":180},
    {"faixa":"Médio-longo (61–90d)",      "col":"De 60 a 91",    "meta":80000, "premio":210},
    {"faixa":"Longo prazo (91–180d)",     "col":"De 91 a  180",  "meta":70000, "premio":260},
    {"faixa":"Muito atrasado (181–360d)", "col":"De 181 360",    "meta":50000, "premio":260},
    {"faixa":"Perdido (>360d)",           "col":"Maior que 360", "meta":50000, "premio":300},
    {"faixa":"Juros",                      "col":"Vlr Calculado", "meta":80000, "premio":400},
]
ORDEM_FAIXAS = [m["faixa"] for m in METAS]
COBRADORES_INATIVOS = {"PEDRO.SILVA"}
PREMIOS_LIDER_CARTEIRA = {1:100, 2:300, 3:500}

def fmt_br(v):
    try:
        v2 = float(v)
        if v2!=v2: v2=0.0
        return f"R$ {v2:,.2f}".replace(",","X").replace(".",",").replace("X",".")
    except: return "R$ 0,00"

def safe_float(v):
    try:
        s=str(v).strip().replace(",",".")
        return 0.0 if s in ("","nan","None","-") else float(s)
    except: return 0.0

def has_ticket(s): return bool(re.search(r'ticket|devolu[cç][aã]o', str(s or ''), re.IGNORECASE))

def get_faixa(row):
    cols=[("De 0 a 30","Curto prazo (10–30d)"),("De 31 a 60","Médio prazo (31–60d)"),
          ("De 60 a 91","Médio-longo (61–90d)"),("De 91 a  180","Longo prazo (91–180d)"),
          ("De 181 360","Muito atrasado (181–360d)"),("Maior que 360","Perdido (>360d)")]
    for col,label in cols:
        if safe_float(row.get(col,0))>0: return label
    return "—"

def load_relatorio(file):
    ext=file.name.split(".")[-1].lower()
    eng="openpyxl" if ext=="xlsx" else None
    raw=pd.read_excel(file,header=None,dtype=str,engine=eng)
    hidx=None
    for i,row in raw.iterrows():
        if "Cobrador" in row.values: hidx=i; break
    if hidx is None: raise ValueError("Coluna 'Cobrador' não encontrada.")
    df=pd.read_excel(file,skiprows=hidx,dtype=str,engine=eng)
    df.columns=df.columns.str.strip()
    df=df[df["Cobrador"].notna()&(df["Cobrador"].str.strip()!="")]
    return df

def load_carteira(file):
    df=pd.read_excel(file,header=0)
    df.columns=df.columns.str.strip()
    df=df[df["Pos."].apply(lambda x:str(x).strip().isdigit())]
    df["Em Atraso"]=pd.to_numeric(df["Em Atraso"],errors="coerce").fillna(0)
    df["cod_matriz"]=df["cod_matriz"].astype(str).str.strip()
    return df

