# ══════════════════════════════════════════════════════════════════════════
# PÁGINA 1 — COBRADORES
# ══════════════════════════════════════════════════════════════════════════
if pagina=="Cobradores":
    st.markdown("<div class='page-title'>Premiação dos Cobradores</div>", unsafe_allow_html=True)
    st.markdown("<div class='page-sub'>Apuração mensal · metas por equipe · prêmio tudo ou nada por faixa</div>", unsafe_allow_html=True)

    uploaded=st.file_uploader("Importar relatório mensal (.xls / .xlsx)", type=["xls","xlsx"])
    if not uploaded:
        st.markdown('<div class="info-strip">Faça o upload do relatório mensal exportado do sistema para calcular a premiação automaticamente.</div>', unsafe_allow_html=True)
        st.stop()

    try: df_raw=load_relatorio(uploaded)
    except Exception as e: st.error(f"Erro ao ler arquivo: {e}"); st.stop()

    # Só boletos (excluir depósito bancário, PIX, dinheiro etc.)
    TIPOS_VALIDOS = ["BOLETO", "BOLETO RETORNO", "BOLETO RETORNO/TITULO VENCIDO", "BOLETO REGISTRADO"]
    if "Tipo de Título" in df_raw.columns:
        df_boletos = df_raw[df_raw["Tipo de Título"].str.upper().str.strip().str.startswith("BOLETO")]
    else:
        df_boletos = df_raw
    excluidos=df_boletos[df_boletos["Histórico"].apply(has_ticket)]
    clean=df_boletos[~df_boletos["Histórico"].apply(has_ticket)].copy()
    for m in METAS: clean[m["col"]]=clean[m["col"]].apply(safe_float)

    # ── Estado: clientes excluídos manualmente ──
    if "excluidos_manual" not in st.session_state:
        st.session_state.excluidos_manual=set()

    cobradores_list=sorted(clean["Cobrador"].dropna().unique())

    totais={}; clientes_por={}
    for nome in cobradores_list:
        sub=clean[clean["Cobrador"]==nome]
        totais[nome]={m["col"]:sub[m["col"]].sum() for m in METAS}
        clientes_por[nome]=sub

    # Calcular totais excluindo os manuais
    def get_clean_filtered():
        if not st.session_state.excluidos_manual: return clean
        return clean[~clean["Parceiro"].isin(st.session_state.excluidos_manual)]

    def recalc_totais():
        cf=get_clean_filtered()
        te={m["col"]:cf[m["col"]].sum() for m in METAS}
        fok={m["col"]:te[m["col"]]>=m["meta"] for m in METAS}
        tot={}
        for nome in cobradores_list:
            sub=cf[cf["Cobrador"]==nome]
            tot[nome]={m["col"]:sub[m["col"]].sum() for m in METAS}
        return te,fok,tot

    total_equipe,faixas_ok,totais=recalc_totais()
    premio_cobrador=sum(m["premio"]/2 for m in METAS if faixas_ok[m["col"]])

    # KPIs
    c1,c2,c3,c4 = st.columns(4)
    c1.markdown(f'<div style="background:white;border-radius:10px;padding:1rem 1.25rem;border:1px solid #e8eaf0;border-top:3px solid #041747"><div style="font-size:10px;color:#9ca3af;text-transform:uppercase;font-weight:700;margin-bottom:4px">Cobradores</div><div style="font-size:22px;font-weight:800;color:#041747">{len(cobradores_list)}</div></div>', unsafe_allow_html=True)
    c2.markdown(f'<div style="background:white;border-radius:10px;padding:1rem 1.25rem;border:1px solid #e8eaf0;border-top:3px solid #041747"><div style="font-size:10px;color:#9ca3af;text-transform:uppercase;font-weight:700;margin-bottom:4px">Registros validos</div><div style="font-size:22px;font-weight:800;color:#041747">{len(get_clean_filtered())}</div></div>', unsafe_allow_html=True)
    n_excl_total = len(excluidos) + len(st.session_state.excluidos_manual)
    c3.markdown(f'<div style="background:white;border-radius:10px;padding:1rem 1.25rem;border:1px solid #e8eaf0;border-top:3px solid #FAC318"><div style="font-size:10px;color:#9ca3af;text-transform:uppercase;font-weight:700;margin-bottom:4px">Excluidos</div><div style="font-size:22px;font-weight:800;color:#b45309">{n_excl_total}</div></div>', unsafe_allow_html=True)
    c4.markdown(f'<div style="background:white;border-radius:10px;padding:1rem 1.25rem;border:1px solid #e8eaf0;border-top:3px solid #0F8C3B"><div style="font-size:10px;color:#9ca3af;text-transform:uppercase;font-weight:700;margin-bottom:4px">Premio por cobrador</div><div style="font-size:22px;font-weight:800;color:#0F8C3B">{fmt_br(premio_cobrador)}</div></div>', unsafe_allow_html=True)
    st.markdown("<br>", unsafe_allow_html=True)

    # ── Cards por cobrador ──
    for nome in cobradores_list:
        d=totais[nome]
        inativo=nome in COBRADORES_INATIVOS
        premio_total=0.0 if inativo else sum(m["premio"]/2 for m in METAS if faixas_ok[m["col"]])
        nome_display=nome.replace("."," ").title()
        initials="".join(p[0] for p in nome.split("."))[:2].upper()
        prize_cls="zero" if (inativo or premio_total==0) else "green"
        icon="🔴" if inativo else ("🟢" if premio_total>0 else "🟡")

        with st.expander(f"{nome_display} - {fmt_br(premio_total)} {icon}", expanded=not inativo):
            inativo_html='<span style="background:#fee2e2;color:#991b1b;padding:2px 10px;border-radius:20px;font-size:11px;font-weight:700;margin-left:8px">Inativo · sem premiação</span>' if inativo else ""
            prize_color = "#0F8C3B" if (not inativo and premio_total > 0) else "#d1d5db"
            st.markdown(
                f'<div style="display:flex;align-items:center;justify-content:space-between;padding-bottom:12px;border-bottom:1px solid #f0f0f0;margin-bottom:14px">' +
                f'<div style="display:flex;align-items:center;gap:12px">' +
                f'<div style="width:42px;height:42px;border-radius:50%;background:#041747;display:flex;align-items:center;justify-content:center;font-size:14px;font-weight:800;color:white">{initials}</div>' +
                f'<div><div style="font-size:16px;font-weight:800;color:#041747">{nome_display} {inativo_html}</div>' +
                f'<div style="font-size:11px;color:#9ca3af;font-weight:600;margin-top:2px">COBRADOR</div></div></div>' +
                f'<div style="text-align:right"><div style="font-size:10px;color:#9ca3af;font-weight:700;text-transform:uppercase;letter-spacing:.06em">PREMIACAO DO MES</div>' +
                f'<div style="font-size:24px;font-weight:800;color:{prize_color}">{fmt_br(premio_total)}</div></div></div>',
                unsafe_allow_html=True
            )

            sub_cli=clientes_por[nome]
            n_excl_cob=len(excluidos[excluidos["Cobrador"]==nome])
            tab_prem,tab_cli,tab_excl=st.tabs([
                "Premiacao por faixa",
                f"Clientes ({len(sub_cli)})",
                f"Excluidos ({n_excl_cob})",
            ])

            # ── Tab premiação ──
            with tab_prem:
                rows_data=[]
                for m in METAS:
                    val_ind=d[m["col"]]
                    val_grp=total_equipe[m["col"]]
                    atingiu=faixas_ok[m["col"]]
                    # % corretos: em relação à meta (0-100+)
                    pct_grp_num=round(val_grp/m["meta"]*100,1) if m["meta"]>0 else 0.0
                    pct_ind_num=round(val_ind/m["meta"]*100,1) if m["meta"]>0 else 0.0
                    pct_part=round(val_ind/val_grp*100,1) if val_grp>0 else 0.0
                    faltou=max(0,m["meta"]-val_grp)

                    if inativo: premio_f,status="R$ 0,00","Inativo"
                    elif atingiu: premio_f,status=fmt_br(m["premio"]/2),"Batida"
                    else: premio_f,status="—","Nao batida"

                    rows_data.append({
                        "Faixa":m["faixa"],
                        "Você recuperou":fmt_br(val_ind),
                        "Sua contrib.":f"{pct_ind_num:.1f}%",
                        "% do total equipe":f"{pct_part:.1f}%",
                        "Total equipe":fmt_br(val_grp),
                        "Meta":fmt_br(m["meta"]),
                        "Progresso equipe (%)":pct_grp_num,
                        "Status":status,
                        "Prêmio":premio_f,
                    })

                df_prem=pd.DataFrame(rows_data)
                # Ordenar por ordem correta das faixas
                df_prem["_ord"]=df_prem["Faixa"].apply(lambda x: ORDEM_FAIXAS.index(x) if x in ORDEM_FAIXAS else 99)
                df_prem=df_prem.sort_values("_ord").drop(columns=["_ord"])

                st.dataframe(df_prem, use_container_width=True, hide_index=True,
                    column_config={
                        "Progresso equipe (%)": st.column_config.ProgressColumn(
                            "Progresso equipe", min_value=0, max_value=100, format="%.1f%%"
                        ),
                    }
                )
                if not inativo:
                    faixas_ganhas=[m for m in METAS if faixas_ok[m["col"]]]
                    faixas_perdidas=[m for m in METAS if not faixas_ok[m["col"]]]
                    linhas_g="".join(
                        f"<li><b>{m['faixa']}</b>: equipe recuperou {fmt_br(total_equipe[m['col']])} "
                        f"(meta {fmt_br(m['meta'])}) → prêmio <b style='color:{GREEN}'>{fmt_br(m['premio']/2)}</b> por cobrador</li>"
                        for m in faixas_ganhas)
                    linhas_p="".join(
                        f"<li><b>{m['faixa']}</b>: equipe fez {fmt_br(total_equipe[m['col']])} "
                        f"de {fmt_br(m['meta'])} — faltou {fmt_br(max(0,m['meta']-total_equipe[m['col']]))}</li>"
                        for m in faixas_perdidas)
                    resumo="".join([
                        f"<b style='color:#065f46'>✅ Faixas premiadas:</b><ul>{linhas_g}</ul>" if linhas_g else "",
                        f"<b style='color:#991b1b'>❌ Não premiadas:</b><ul>{linhas_p}</ul>" if linhas_p else "",
                        f"<b>Total do mês: {fmt_br(premio_total)}</b>",
                    ])
                    st.markdown(f'<div class="info-strip" style="margin-top:10px">{resumo}</div>', unsafe_allow_html=True)

            # ── Tab clientes ──
            with tab_cli:
                grupos=defaultdict(lambda:{"vlr":0.0,"juros":0.0,"faixas":set(),"baixas":[]})
                for _,row in sub_cli.iterrows():
                    parc=str(row.get("Parceiro","") or "").strip()
                    grupos[parc]["vlr"]+=safe_float(row.get("Vlr.Desdob.",0))
                    grupos[parc]["juros"]+=safe_float(row.get("Vlr Calculado",0))
                    f=get_faixa(row)
                    if f!="—": grupos[parc]["faixas"].add(f)
                    b=str(row.get("Baixa","") or "").split(" ")[0].split("T")[0]
                    if b and b not in grupos[parc]["baixas"]: grupos[parc]["baixas"].append(b)

                df_cli=pd.DataFrame([{
                    "✓":parc not in st.session_state.excluidos_manual,
                    "Parceiro":parc,
                    "Total recuperado":g["vlr"],
                    "Faixa":", ".join(
                        sorted(g["faixas"], key=lambda x: ORDEM_FAIXAS.index(x) if x in ORDEM_FAIXAS else 99)
                    ) or "—",
                    "Datas de baixa":", ".join(sorted(set(g["baixas"]))),
                    "Juros/multa":g["juros"],
                } for parc,g in sorted(grupos.items(),key=lambda x:-x[1]["vlr"])])

                if df_cli.empty:
                    st.info("Nenhum cliente recuperado.")
                else:
                    col_busca, col_faixa = st.columns([2,1])
                    with col_busca:
                        busca=st.text_input("Buscar cliente",key=f"busca_{nome}",placeholder="Nome do parceiro...")
                    with col_faixa:
                        faixas_disp=["Todas"]+ORDEM_FAIXAS[:-1]+["Juros + multa"]
                        filtro_faixa=st.selectbox("Filtrar faixa",faixas_disp,key=f"faixa_{nome}")

                    df_show=df_cli.copy()
                    if busca: df_show=df_show[df_show["Parceiro"].str.contains(busca,case=False,na=False)]
                    if filtro_faixa!="Todas": df_show=df_show[df_show["Faixa"].str.contains(filtro_faixa,na=False)]

                    edited=st.data_editor(
                        df_show, use_container_width=True, hide_index=True,
                        column_config={
                            "✓": st.column_config.CheckboxColumn("Contabilizar",help="Desmarque para tirar da premiação"),
                            "Total recuperado": st.column_config.NumberColumn("Total recuperado",format="R$ %.2f"),
                            "Juros/multa": st.column_config.NumberColumn("Juros/multa",format="R$ %.2f"),
                        },
                        disabled=["Parceiro","Total recuperado","Faixa","Datas de baixa","Juros/multa"],
                    )

                    # Atualizar set de excluídos manuais
                    desmarcados=set(edited[~edited["✓"]]["Parceiro"].tolist())
                    marcados=set(edited[edited["✓"]]["Parceiro"].tolist())
                    st.session_state.excluidos_manual=(st.session_state.excluidos_manual|desmarcados)-marcados

                    if desmarcados:
                        st.warning(f"{len(desmarcados)} parceiro(s) excluidos manualmente. Clique em outro cobrador e volte para ver o recalculo.")
                        if st.button("Recalcular agora", key=f"recalc_{nome}"):
                            total_equipe,faixas_ok,totais=recalc_totais()
                            st.rerun()

                    st.caption(f"{len(df_show)} parceiros · Total: {fmt_br(df_show['Total recuperado'].sum())}")

            # ── Tab excluídos ──
            with tab_excl:
                excl_cob=excluidos[excluidos["Cobrador"]==nome].copy()
                if excl_cob.empty: st.info("Nenhum registro excluído.")
                else:
                    df_excl=excl_cob[["Parceiro","Vencimento","Vlr.Desdob.","Histórico"]].copy()
                    df_excl.columns=["Parceiro","Vencimento","Valor","Histórico"]
                    df_excl["Valor"]=df_excl["Valor"].apply(safe_float)
                    st.dataframe(df_excl,use_container_width=True,hide_index=True,
                        column_config={"Valor":st.column_config.NumberColumn("Valor",format="R$ %.2f")})

    # ── Card líderes ──
    st.markdown(f'<div style="color:{NAVY};font-size:16px;font-weight:800;margin:2rem 0 .5rem">Premiação dos Líderes (aging)</div>', unsafe_allow_html=True)
    premio_lider=sum(m["premio"]/2 for m in METAS if faixas_ok[m["col"]])
    rows_lid=[{
        "Faixa":m["faixa"],
        "Total equipe":fmt_br(total_equipe[m["col"]]),
        "Meta":fmt_br(m["meta"]),
        "Progresso (%)":round(total_equipe[m["col"]]/m["meta"]*100,1),
        "Status":"Batida" if faixas_ok[m["col"]] else "Nao batida",
        "Prêmio/líder":fmt_br(m["premio"]/2) if faixas_ok[m["col"]] else "—",
    } for m in METAS]
    col_l,col_r=st.columns([3,1])
    with col_l:
        st.dataframe(pd.DataFrame(rows_lid),use_container_width=True,hide_index=True,
            column_config={"Progresso (%)":st.column_config.ProgressColumn("Progresso",min_value=0,max_value=100,format="%.1f%%")})
    with col_r:
        st.markdown(f'<div style="background:white;border-radius:10px;padding:1rem 1.25rem;border:1px solid #e8eaf0;border-top:3px solid #0F8C3B;margin-top:8px"><div style="font-size:10px;color:#9ca3af;text-transform:uppercase;font-weight:700;margin-bottom:4px">Premio por lider</div><div style="font-size:22px;font-weight:800;color:#0F8C3B">{fmt_br(premio_lider)}</div><div style="font-size:11px;color:#9ca3af;margin-top:4px">Teto: R$ 935,00</div></div>', unsafe_allow_html=True)


